type ExtractParams<Path extends string> =
  Path extends `${infer _Start}:${infer Param}/${infer Rest}`
    ? { [K in Param | keyof ExtractParams<`/${Rest}`>]: string }
    : Path extends `${infer _Start}:${infer Param}`
      ? { [K in Param]: string }
      : {};

type OrderRouteParams = ExtractParams<'/users/:id/orders/:orderId'>;
// équivalent à { id: string; orderId: string }

function handleRoute(params: OrderRouteParams): void {
  console.log(params.id, params.orderId);
}

