export {};

// TODO 1 : remplace string par le type littéral de gabarit `${T}:created`
type EventName<T extends string> = string;

// TODO 2 : type conditionnel : si T est un tableau (T extends readonly (infer U)[]) alors U, sinon T
type ElementOf<T> = T;

function eventName<T extends string>(entity: T): EventName<T> {
  // TODO 3 : retourne `${entity}:created`
  return entity as EventName<T>;
}

function first<T>(value: T): ElementOf<T> {
  // TODO 4 : retourne le premier élément si value est un tableau, sinon value lui-même
  return value as ElementOf<T>;
}

const created: string = eventName('user');
console.log(created);
console.log(eventName('order'));
console.log(`first([1, 2]) = ${first([1, 2])}`);
console.log(`first("x") = ${first('x')}`);
